// ASTRA service worker. Generated by tools/postbuild.mjs — edit the template.
//
//  - Shell, road network, sealed route, glyphs: precached; served cache-first
//    so the app opens with no signal. Navigation is network-first (3 s) so a
//    new release arrives on the next launch with signal.
//  - City feeds and radar: never cached here. Live data must not be replayed
//    as if it were live; the app keeps its own timestamped last snapshot.
//  - City orthophoto tiles: cache-first in their own capped cache.

const VERSION = '__VERSION__';
const SHELL = `astra-shell-${VERSION}`;
const ORTHO = 'astra-ortho-v1';
const ORTHO_MAX = 4000;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const c = await caches.open(SHELL);
      await c.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const k of await caches.keys()) if (k.startsWith('astra-shell-') && k !== SHELL) await caches.delete(k);
      await self.clients.claim();
    })(),
  );
});

async function trimOrtho() {
  const c = await caches.open(ORTHO);
  const keys = await c.keys();
  for (let i = 0; i < keys.length - ORTHO_MAX; i++) await c.delete(keys[i]);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  if (url.hostname === 'gisapps.barrie.ca' && url.pathname.includes('/Barrie_Ortho_2023_10cm_Cache_WebMercator/MapServer/tile/')) {
    event.respondWith(
      (async () => {
        const c = await caches.open(ORTHO);
        const hit = await c.match(req, { ignoreVary: true });
        if (hit) return hit;
        const res = await fetch(req);
        if (res.ok) {
          await c.put(req, res.clone());
          if (Math.random() < 0.02) trimOrtho();
        }
        return res;
      })(),
    );
    return;
  }

  if (url.origin !== self.location.origin) return; // City feeds, radar: straight to the network

  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        const c = await caches.open(SHELL);
        try {
          const res = await Promise.race([fetch(req), new Promise((_, rej) => setTimeout(() => rej(new Error('slow')), 3000))]);
          if (res.ok) c.put('/index.html', res.clone());
          return res;
        } catch {
          return (await c.match('/index.html')) || (await c.match('/')) || Response.error();
        }
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const c = await caches.open(SHELL);
      const hit = await c.match(req, { ignoreSearch: url.pathname.startsWith('/fonts/') });
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok && (url.pathname.startsWith('/assets/') || url.pathname.startsWith('/fonts/') || url.pathname.startsWith('/data/'))) c.put(req, res.clone());
      return res;
    })(),
  );
});
